1	"use client";
2	
3	import { useState } from "react";
4	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
5	import { Button } from "@/components/ui/button";
6	import { Input } from "@/components/ui/input";
7	import { Textarea } from "@/components/ui/textarea";
8	import { Label } from "@/components/ui/label";
9	import { toast } from "sonner";
10	import { Copy, Mail, Link2, Code, Check } from "lucide-react";
11	import FormBuilder from "@/components/FormBuilder";
12	import AutoAckSettings from "@/components/AutoAckSettings";
13	import JobDistributionPanel from "@/components/JobDistributionPanel";
14	
15	interface JobSettingsTabProps {
16	  jobId: string;
17	  jobTitle: string;
18	  jobSlug?: string | null;
19	  inboxEmail?: string | null;
20	  teamId?: string | null;
21	  careerPageActive?: boolean;
22	  appUrl?: string;
23	}
24	
25	/**
26	 * Unified settings tab for a single job. Replaces the old scattered config:
27	 * Applications tab (FormBuilder + AutoAck), Distribute tab, and inbox email
28	 * notice. Gives the user ONE place to configure every intake channel, every
29	 * form field, and every auto-reply for this job.
30	 */
31	export default function JobSettingsTab({
32	  jobId,
33	  jobTitle,
34	  jobSlug,
35	  inboxEmail,
36	  teamId,
37	  careerPageActive,
38	  appUrl,
39	}: JobSettingsTabProps) {
40	  const [copiedKey, setCopiedKey] = useState<string | null>(null);
41	
42	  const baseUrl = appUrl ?? (typeof window !== "undefined" ? window.location.origin : "");
43	  const applyUrl = `${baseUrl}/apply/${jobId}`;
44	  const embedSnippet = `<iframe src="${applyUrl}" width="100%" height="800" frameborder="0" title="Apply for ${jobTitle}"></iframe>`;
45	
46	  const copy = async (value: string, key: string) => {
47	    try {
48	      await navigator.clipboard.writeText(value);
49	      setCopiedKey(key);
50	      toast.success("Copied to clipboard");
51	      setTimeout(() => setCopiedKey(null), 1500);
52	    } catch {
53	      toast.error("Failed to copy");
54	    }
55	  };
56	
57	  return (
58	    <div className="space-y-6">
59	      {/* ── Intake channels ─────────────────────────────────────────────── */}
60	      <Card>
61	        <CardHeader className="pb-3">
62	          <CardTitle className="text-base flex items-center gap-2">
63	            <Link2 className="h-4 w-4 text-primary" />
64	            Intake channels
65	          </CardTitle>
66	          <p className="text-xs text-muted-foreground">
67	            How candidates reach this job. All inbound resumes get AI-ranked automatically.
68	          </p>
69	        </CardHeader>
70	        <CardContent className="space-y-5">
71	          {/* Public apply link */}
72	          <div className="space-y-1.5">
73	            <Label className="text-xs font-medium">Public apply link</Label>
74	            <div className="flex items-center gap-2">
75	              <Input
76	                value={applyUrl}
77	                readOnly
78	                className="h-8 text-xs font-mono"
79	                onClick={(e) => (e.target as HTMLInputElement).select()}
80	              />
81	              <Button
82	                variant="outline"
83	                size="sm"
84	                className="h-8 shrink-0 gap-1.5"
85	                onClick={() => copy(applyUrl, "apply")}
86	              >
87	                {copiedKey === "apply" ? <Check className="h-3.5 w-3.5 text-emerald-600" /> : <Copy className="h-3.5 w-3.5" />}
88	                Copy
89	              </Button>
90	            </div>
91	            <p className="text-[11px] text-muted-foreground">
92	              Share this link anywhere. Candidates fill the form below and their resumes land in the Candidates tab, scored.
93	            </p>
94	          </div>
95	
96	          {/* Resume inbox email */}
97	          {inboxEmail && (
98	            <div className="space-y-1.5">
99	              <Label className="text-xs font-medium flex items-center gap-1.5">
100	                <Mail className="h-3.5 w-3.5" />
101	                Resume inbox email
102	              </Label>
103	              <div className="flex items-center gap-2">
104	                <Input
105	                  value={inboxEmail}
106	                  readOnly
107	                  className="h-8 text-xs font-mono"
108	                  onClick={(e) => (e.target as HTMLInputElement).select()}
109	                />
110	                <Button
111	                  variant="outline"
112	                  size="sm"
113	                  className="h-8 shrink-0 gap-1.5"
114	                  onClick={() => copy(inboxEmail, "inbox")}
115	                >
116	                  {copiedKey === "inbox" ? <Check className="h-3.5 w-3.5 text-emerald-600" /> : <Copy className="h-3.5 w-3.5" />}
117	                  Copy
118	                </Button>
119	              </div>
120	              <p className="text-[11px] text-muted-foreground">
121	                Forward any candidate email to this address — resumes extracted automatically.
122	              </p>
123	            </div>
124	          )}
125	
126	          {/* Embed snippet */}
127	          <div className="space-y-1.5">
128	            <Label className="text-xs font-medium flex items-center gap-1.5">
129	              <Code className="h-3.5 w-3.5" />
130	              Embed on your website
131	            </Label>
132	            <div className="flex items-start gap-2">
133	              <Textarea
134	                value={embedSnippet}
135	                readOnly
136	                rows={2}
137	                className="text-[11px] font-mono resize-none"
138	                onClick={(e) => (e.target as HTMLTextAreaElement).select()}
139	              />
140	              <Button
141	                variant="outline"
142	                size="sm"
143	                className="h-8 shrink-0 gap-1.5"
144	                onClick={() => copy(embedSnippet, "embed")}
145	              >
146	                {copiedKey === "embed" ? <Check className="h-3.5 w-3.5 text-emerald-600" /> : <Copy className="h-3.5 w-3.5" />}
147	                Copy
148	              </Button>
149	            </div>
150	            <p className="text-[11px] text-muted-foreground">
151	              Paste this iframe on your careers page, landing page, or any public site.
152	            </p>
153	          </div>
154	        </CardContent>
155	      </Card>
156	
157	      {/* ── Distribution (LinkedIn, Indeed, X, Google Jobs) ─────────────── */}
158	      <JobDistributionPanel
159	        jobId={jobId}
160	        jobTitle={jobTitle}
161	        slug={jobSlug ?? null}
162	        teamId={teamId ?? null}
163	        careerPageActive={careerPageActive ?? false}
164	      />
165	
166	      {/* ── Application form builder ────────────────────────────────────── */}
167	      <FormBuilder jobId={jobId} />
168	
169	      {/* ── Auto-acknowledgement email ──────────────────────────────────── */}
170	      <AutoAckSettings jobId={jobId} />
171	    </div>
172	  );
173	}
