1	"use client";
2	
3	import { useEffect } from "react";
4	import { useParams, useRouter } from "next/navigation";
5	import Link from "next/link";
6	import { useQuery } from "@tanstack/react-query";
7	import { supabase } from "@/integrations/supabase/client";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { Badge } from "@/components/ui/badge";
10	import { Button } from "@/components/ui/button";
11	import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
12	import { toast } from "sonner";
13	import {
14	  Briefcase,
15	  MapPin,
16	  Building2,
17	  Clock,
18	  DollarSign,
19	  Layers,
20	  ArrowLeft,
21	  Linkedin,
22	  Twitter,
23	  Link2,
24	  Calendar,
25	} from "lucide-react";
26	import { formatDistanceToNow } from "date-fns";
27	
28	// ─── Types ───────────────────────────────────────────────────────────────────
29	
30	interface CareerConfig {
31	  company_name: string;
32	  logo_url: string | null;
33	  brand_color: string;
34	  tagline: string | null;
35	  about: string | null;
36	}
37	
38	interface JobDetail {
39	  id: string;
40	  title: string;
41	  job_description: string | null;
42	  location: string | null;
43	  department: string | null;
44	  employment_type: string | null;
45	  salary_range: string | null;
46	  created_at: string;
47	  is_published: boolean;
48	}
49	
50	interface RelatedJob {
51	  id: string;
52	  title: string;
53	  location: string | null;
54	  department: string | null;
55	  employment_type: string | null;
56	  created_at: string;
57	}
58	
59	// ─── Sub-components ──────────────────────────────────────────────────────────
60	
61	function CareerHeader({
62	  config,
63	  slug,
64	}: {
65	  config: CareerConfig | null | undefined;
66	  slug: string | undefined;
67	}) {
68	  return (
69	    <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
70	      <div className="max-w-5xl mx-auto px-4 py-4 flex items-center gap-3">
71	        {config?.logo_url ? (
72	          <img
73	            src={config.logo_url}
74	            alt={config.company_name}
75	            className="h-8 w-8 rounded object-cover"
76	          />
77	        ) : (
78	          <div className="h-8 w-8 rounded bg-primary/10 flex items-center justify-center">
79	            <Layers className="h-4 w-4 text-primary" />
80	          </div>
81	        )}
82	        <Link
83	          href={slug ? `/careers/${slug}` : "/"}
84	          className="font-semibold text-lg text-foreground hover:text-primary transition-colors"
85	        >
86	          {config?.company_name ?? "Careers"}
87	        </Link>
88	      </div>
89	    </header>
90	  );
91	}
92	
93	function CareerFooter() {
94	  return (
95	    <footer className="py-6 text-center border-t border-border space-y-2">
96	      <p className="text-xs text-muted-foreground">
97	        Powered by{" "}
98	        <Link
99	          href="/"
100	          className="text-primary font-medium hover:text-primary/80 transition-colors"
101	        >
102	          Rankora
103	        </Link>
104	      </p>
105	      <p className="text-[10px] text-muted-foreground/50 max-w-md mx-auto">
106	        By applying, you agree that your information will be processed by the hiring company for recruitment purposes.
107	      </p>
108	    </footer>
109	  );
110	}
111	
112	function SocialShareButtons({
113	  jobId,
114	  title,
115	  brandColor,
116	}: {
117	  jobId: string;
118	  title: string;
119	  brandColor: string;
120	}) {
121	  const applyUrl = `${window.location.origin}/apply/${jobId}`;
122	  const shareText = `${title} — Check out this position`;
123	
124	  return (
125	    <TooltipProvider>
126	      <div className="flex items-center gap-1">
127	        <Tooltip>
128	          <TooltipTrigger asChild>
129	            <button
130	              onClick={() =>
131	                window.open(
132	                  `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(applyUrl)}`,
133	                  "_blank",
134	                  "noopener,noreferrer,width=600,height=500"
135	                )
136	              }
137	              className="h-7 w-7 rounded flex items-center justify-center text-muted-foreground/50 hover:text-[#0A66C2] transition-colors"
138	              aria-label="Share on LinkedIn"
139	            >
140	              <Linkedin className="h-3.5 w-3.5" />
141	            </button>
142	          </TooltipTrigger>
143	          <TooltipContent>Share on LinkedIn</TooltipContent>
144	        </Tooltip>
145	        <Tooltip>
146	          <TooltipTrigger asChild>
147	            <button
148	              onClick={() =>
149	                window.open(
150	                  `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(applyUrl)}`,
151	                  "_blank",
152	                  "noopener,noreferrer,width=600,height=400"
153	                )
154	              }
155	              className="h-7 w-7 rounded flex items-center justify-center text-muted-foreground/50 hover:text-foreground transition-colors"
156	              aria-label="Share on X"
157	            >
158	              <Twitter className="h-3.5 w-3.5" />
159	            </button>
160	          </TooltipTrigger>
161	          <TooltipContent>Share on X</TooltipContent>
162	        </Tooltip>
163	        <Tooltip>
164	          <TooltipTrigger asChild>
165	            <button
166	              onClick={() => {
167	                navigator.clipboard.writeText(applyUrl);
168	                toast.success("Link copied");
169	              }}
170	              className="h-7 w-7 rounded flex items-center justify-center text-muted-foreground/50 hover:text-foreground transition-colors"
171	              aria-label="Copy link"
172	            >
173	              <Link2 className="h-3.5 w-3.5" />
174	            </button>
175	          </TooltipTrigger>
176	          <TooltipContent>Copy link</TooltipContent>
177	        </Tooltip>
178	      </div>
179	    </TooltipProvider>
180	  );
181	}
182	
183	// ─── Main Page ────────────────────────────────────────────────────────────────
184	
185	export default function CareerJobDetail() {
186	  const params = useParams<{ slug: string; jobId: string }>();
187	  const slug = params?.slug;
188	  const jobId = params?.jobId;
189	  const router = useRouter();
190	
191	  // Fetch job detail (direct query — public, no auth required via is_published check)
192	  const { data: job, isLoading: jobLoading } = useQuery<JobDetail | null>({
193	    queryKey: ["career-job", slug, jobId],
194	    queryFn: async () => {
195	      if (!jobId) return null;
196	      const { data, error } = await (supabase as any)
197	        .from("jobs")
198	        .select(
199	          "id, title, job_description, location, department, employment_type, salary_range, created_at, is_published"
200	        )
201	        .eq("id", jobId)
202	        .eq("is_published", true)
203	        .maybeSingle();
204	      if (error) throw error;
205	      return data as JobDetail | null;
206	    },
207	    enabled: !!jobId,
208	    staleTime: 60_000,
209	  });
210	
211	  // Fetch career config via existing RPC for branding
212	  const { data: pageData, isLoading: configLoading } = useQuery({
213	    queryKey: ["career-page", slug],
214	    queryFn: async () => {
215	      if (!slug) return null;
216	      const { data, error } = await supabase.rpc("get_career_page" as never, {
217	        p_slug: slug,
218	      } as never);
219	      if (error) throw error;
220	      return data as unknown as { config: CareerConfig; jobs: RelatedJob[] } | null;
221	    },
222	    enabled: !!slug,
223	    staleTime: 60_000,
224	  });
225	
226	  const config = pageData?.config;
227	  const brandColor = config?.brand_color ?? "#6366f1";
228	
229	  // Related jobs — other published jobs from this company (exclude current)
230	  const relatedJobs = (pageData?.jobs ?? []).filter(
231	    (j: RelatedJob) => j.id !== jobId
232	  ).slice(0, 3);
233	
234	  // Track view on mount
235	  useEffect(() => {
236	    if (!jobId) return;
237	    (supabase as any)
238	      .rpc("increment_job_view", {
239	        p_job_id: jobId,
240	        p_referrer: document.referrer || null,
241	      })
242	      .catch(() => {
243	        // Silently ignore — tracking must never block the page
244	      });
245	  }, [jobId]);
246	
247	  // SEO meta tags + JSON-LD
248	  useEffect(() => {
249	    if (!job || !config) return;
250	
251	    const pageTitle = `${job.title} at ${config.company_name} | Rankora`;
252	    document.title = pageTitle;
253	
254	    const setMeta = (nameOrProp: string, content: string) => {
255	      const isOg = nameOrProp.startsWith("og:");
256	      const attr = isOg ? "property" : "name";
257	      let el =
258	        document.querySelector(`meta[property="${nameOrProp}"]`) ||
259	        document.querySelector(`meta[name="${nameOrProp}"]`);
260	      if (!el) {
261	        el = document.createElement("meta");
262	        el.setAttribute(attr, nameOrProp);
263	        document.head.appendChild(el);
264	      }
265	      el.setAttribute("content", content);
266	    };
267	
268	    const description =
269	      job.job_description
270	        ? job.job_description.slice(0, 160).replace(/\n/g, " ").trim()
271	        : `${job.title} at ${config.company_name}`;
272	
273	    setMeta("description", description);
274	    setMeta("og:title", pageTitle);
275	    setMeta("og:description", description);
276	    setMeta("og:type", "website");
277	    setMeta("og:url", window.location.href);
278	    if (config.logo_url) setMeta("og:image", config.logo_url);
279	
280	    // Individual JobPosting JSON-LD
281	    const jsonLd: Record<string, unknown> = {
282	      "@context": "https://schema.org",
283	      "@type": "JobPosting",
284	      title: job.title,
285	      description: job.job_description ?? job.title,
286	      datePosted: job.created_at,
287	      directApply: true,
288	      hiringOrganization: {
289	        "@type": "Organization",
290	        name: config.company_name,
291	        ...(config.logo_url ? { logo: config.logo_url } : {}),
292	      },
293	    };
294	
295	    if (job.employment_type) {
296	      jsonLd.employmentType = job.employment_type
297	        .toUpperCase()
298	        .replace(/-/g, "_");
299	    }
300	
301	    if (job.location) {
302	      jsonLd.jobLocation = {
303	        "@type": "Place",
304	        address: {
305	          "@type": "PostalAddress",
306	          addressLocality: job.location,
307	        },
308	      };
309	    }
310	
311	    if (job.salary_range) {
312	      jsonLd.baseSalary = {
313	        "@type": "MonetaryAmount",
314	        description: job.salary_range,
315	      };
316	    }
317	
318	    const applyUrl = `${window.location.origin}/apply/${job.id}`;
319	    jsonLd.url = applyUrl;
320	    jsonLd.applicationContact = {
321	      "@type": "ContactPoint",
322	      url: applyUrl,
323	    };
324	
325	    let script = document.getElementById(
326	      "career-job-jsonld"
327	    ) as HTMLScriptElement | null;
328	    if (!script) {
329	      script = document.createElement("script");
330	      script.id = "career-job-jsonld";
331	      script.setAttribute("type", "application/ld+json");
332	      document.head.appendChild(script);
333	    }
334	    script.textContent = JSON.stringify(jsonLd);
335	
336	    return () => {
337	      document.title = "Rankora";
338	      document.getElementById("career-job-jsonld")?.remove();
339	      // Clean up meta tags added by this page
340	      ["description", "og:title", "og:description", "og:type", "og:url", "og:image"].forEach(
341	        (key) => {
342	          document.querySelector(`meta[property="${key}"]`)?.remove();
343	          document.querySelector(`meta[name="${key}"]`)?.remove();
344	        }
345	      );
346	    };
347	  }, [job, config]);
348	
349	  const isLoading = jobLoading || configLoading;
350	
351	  // ── Loading state ────────────────────────────────────────────────────────
352	  if (isLoading) {
353	    return (
354	      <div className="min-h-screen bg-background flex flex-col">
355	        <header className="border-b border-border">
356	          <div className="max-w-5xl mx-auto px-4 py-4 flex items-center gap-3">
357	            <Skeleton className="h-8 w-8 rounded" />
358	            <Skeleton className="h-5 w-32" />
359	          </div>
360	        </header>
361	        <main className="flex-1 max-w-5xl mx-auto px-4 py-10 w-full">
362	          <Skeleton className="h-4 w-48 mb-6" />
363	          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
364	            <div className="md:col-span-2 space-y-4">
365	              <Skeleton className="h-8 w-3/4" />
366	              <Skeleton className="h-4 w-1/2" />
367	              <div className="space-y-2 mt-6">
368	                {[1, 2, 3, 4, 5].map((i) => (
369	                  <Skeleton key={i} className="h-4 w-full" />
370	                ))}
371	              </div>
372	            </div>
373	            <div className="space-y-4">
374	              <Skeleton className="h-48 w-full rounded-xl" />
375	              <Skeleton className="h-10 w-full rounded-md" />
376	            </div>
377	          </div>
378	        </main>
379	      </div>
380	    );
381	  }
382	
383	  // ── Not found ────────────────────────────────────────────────────────────
384	  if (!job) {
385	    return (
386	      <div className="min-h-screen bg-background flex flex-col">
387	        <CareerHeader config={config} slug={slug} />
388	        <main className="flex-1 flex items-center justify-center px-4 py-16">
389	          <div className="text-center space-y-4">
390	            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
391	              <Briefcase className="h-7 w-7 text-muted-foreground" />
392	            </div>
393	            <h1 className="text-xl font-semibold">Job not found</h1>
394	            <p className="text-sm text-muted-foreground">
395	              This position may have been filled or removed.
396	            </p>
397	            {slug && (
398	              <Link
399	                href={`/careers/${slug}`}
400	                className="text-sm font-medium text-primary hover:text-primary/80 transition-colors"
401	              >
402	                View all open positions
403	              </Link>
404	            )}
405	          </div>
406	        </main>
407	        <CareerFooter />
408	      </div>
409	    );
410	  }
411	
412	  // ── Metadata items ───────────────────────────────────────────────────────
413	  const metadataItems = [
414	    job.location && { icon: MapPin, label: "Location", text: job.location },
415	    job.department && {
416	      icon: Building2,
417	      label: "Department",
418	      text: job.department,
419	    },
420	    job.employment_type && {
421	      icon: Clock,
422	      label: "Type",
423	      text: job.employment_type,
424	    },
425	    job.salary_range && {
426	      icon: DollarSign,
427	      label: "Salary",
428	      text: job.salary_range,
429	    },
430	    {
431	      icon: Calendar,
432	      label: "Posted",
433	      text: formatDistanceToNow(new Date(job.created_at), { addSuffix: true }),
434	    },
435	  ].filter(Boolean) as { icon: typeof MapPin; label: string; text: string }[];
436	
437	  // ── Main render ──────────────────────────────────────────────────────────
438	  return (
439	    <div className="min-h-screen bg-background flex flex-col">
440	      <CareerHeader config={config} slug={slug} />
441	
442	      <main className="flex-1 max-w-5xl mx-auto px-4 py-10 w-full">
443	        {/* Breadcrumb */}
444	        <nav className="flex items-center gap-1.5 text-xs text-muted-foreground mb-6" aria-label="Breadcrumb">
445	          {slug && (
446	            <>
447	              <Link
448	                href={`/careers/${slug}`}
449	                className="hover:text-foreground transition-colors"
450	              >
451	                {config?.company_name ?? "Careers"}
452	              </Link>
453	              <span>/</span>
454	            </>
455	          )}
456	          <span className="text-foreground font-medium truncate max-w-[200px]">
457	            {job.title}
458	          </span>
459	        </nav>
