117	function slugify(name: string): string {
118	  const raw = name
119	    .toLowerCase()
120	    .replace(/[^a-z0-9]+/g, "-")
121	    .replace(/^-|-$/g, "")
122	    .slice(0, 60);
123	  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
124	  if (raw.length < 3) return raw.padEnd(3, "1");
125	  return raw;
126	}
127	
128	// DB constraint only accepts 6-digit hex (#rrggbb).
129	function isValidHex(value: string): boolean {
130	  return /^#[0-9A-Fa-f]{6}$/.test(value);
131	}
